mapper.select:
SELECT v.*
FROM yak_workflow_version v
WHERE v.id = #{id}
  AND v.project_id = #{projectId}
LIMIT 1

mapper.update:
UPDATE yak_workflow_version
SET engine_definition_json = #{engineDefinitionJson}
WHERE id = #{id}
  AND project_id = #{projectId}
  AND engine_definition_json IS NULL

UPDATE yak_workflow_version
SET runtime_metadata_json = #{runtimeMetadataJson}
WHERE id = #{id}
  AND project_id = #{projectId}
  AND runtime_metadata_json IS NULL
